SELECT CASE WHEN budget >= 3825000 THEN 'high' WHEN budget >= 1498000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget, COUNT(*) AS cnt, ROUND(SUM(budget) * 100.0 / SUM(SUM(budget)) OVER (), 2) AS pct_of_total FROM departments WHERE dept_name IN ('Finance', 'Engineering', 'HR') GROUP BY CASE WHEN budget >= 3825000 THEN 'high' WHEN budget >= 1498000 THEN 'mid' ELSE 'low' END ORDER BY cnt DESC
